import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Краткая таблица летописи","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0093-编年史简表.md","filePath":"ru/0093-编年史简表.md"}'),h={name:"ru/0093-编年史简表.md"};function i(o,t,l,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="краткая-таблица-летописи" tabindex="-1">Краткая таблица летописи <a class="header-anchor" href="#краткая-таблица-летописи" aria-label="Permalink to &quot;Краткая таблица летописи&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>93</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>летопись, деление эпох, крупные события, исторические вехи, Вселенная Хэнъюань</td></tr></tbody></table><h2 id="i-пояснения-к-летописи" tabindex="-1">I. Пояснения к летописи <a class="header-anchor" href="#i-пояснения-к-летописи" aria-label="Permalink to &quot;I. Пояснения к летописи&quot;">​</a></h2><p>Настоящая краткая таблица на основе стандартного времени Вселенной Хэнъюань фиксирует крупные исторические события и ключевые вехи развития Симбиотической Цивилизации Якоря в порядке эпох. Временной охват простирается от древнего периода до-якорной эпохи до будущих перспектив эпохи межзвёздного симбиоза. Для каждой эпохи указаны начало и конец, характерные черты и крупные события. Настоящая таблица представляет собой предельно сжатый исторический индекс; подробную историю каждой эпохи см. в специальных описаниях документов 70–79.</p><h2 id="ii-обзор-деления-эпох" tabindex="-1">II. Обзор деления эпох <a class="header-anchor" href="#ii-обзор-деления-эпох" aria-label="Permalink to &quot;II. Обзор деления эпох&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер эпохи</th><th>Название эпохи</th><th>Период (стандартные годы Вселенной Хэнъюань)</th><th>Продолжительность</th><th>Ключевые черты</th></tr></thead><tbody><tr><td>Первая эпоха</td><td>До-якорная эпоха</td><td>ок. −10 млрд лет до −10 000 лет</td><td>ок. 10 млрд лет</td><td>Господство хищнических систем культивации; цивилизации возвышались и рушились циклически</td></tr><tr><td>Вторая эпоха</td><td>Эпоха Пробуждения Якоря</td><td>−10 000 до −1000 лет</td><td>ок. 9000 лет</td><td>Механизм Якоря был открыт и впервые применён</td></tr><tr><td>Третья эпоха</td><td>Период установления симбиотической системы</td><td>−1000 до −100 лет</td><td>ок. 900 лет</td><td>Постепенно формировался институциональный каркас Симбиотической Цивилизации Якоря</td></tr><tr><td>Четвёртая эпоха</td><td>Период открытия Трёхсот Систем</td><td>−100 до −50 лет</td><td>ок. 50 лет</td><td>Триста Исходных Систем Культивации были полностью открыты</td></tr><tr><td>Пятая эпоха</td><td>Период Стратегии активации 20 %</td><td>−50 лет до первого года</td><td>ок. 50 лет</td><td>20 % живых существ были активированы в Верховных Силачей Плоскости</td></tr><tr><td>Шестая эпоха</td><td>Эпоха первого возвышения</td><td>первый год до 100</td><td>100 лет</td><td>Симбиотическая цивилизация впервые осуществила поэтапное возвышение</td></tr><tr><td>Седьмая эпоха</td><td>Эпоха Республики Десяти Тысяч Рас</td><td>100 до 500</td><td>400 лет</td><td>Республика Десяти Тысяч Рас официально учреждена; межрасовая интеграция углубилась</td></tr><tr><td>Восьмая эпоха</td><td>Эпоха межплоскостных исследований</td><td>500 до 2000</td><td>1500 лет</td><td>Развернулись масштабные межплоскостные исследования и археология</td></tr><tr><td>Девятая эпоха</td><td>Эпоха межзвёздного симбиоза</td><td>2000 до будущего</td><td>продолжается</td><td>Создана вселенская сеть симбиоза; продвигается общее возвышение</td></tr></tbody></table><p>Примечание: «первый год» означает год официального провозглашения Симбиотической Цивилизации Якоря, служащий рубежом исторического летосчисления.</p><h2 id="iii-до-якорная-эпоха-ок-−10-млрд-лет-до-−10-000-лет" tabindex="-1">III. До-якорная эпоха (ок. −10 млрд лет до −10 000 лет) <a class="header-anchor" href="#iii-до-якорная-эпоха-ок-−10-млрд-лет-до-−10-000-лет" aria-label="Permalink to &quot;III. До-якорная эпоха (ок. −10 млрд лет до −10 000 лет)&quot;">​</a></h2><p>До-якорная эпоха была самой продолжительной эпохой в истории Вселенной Хэнъюань, длившейся около десяти миллиардов лет. Её ключевой чертой было господство хищнических систем культивации над вселенной, при котором цивилизации бесконечно проходили цикл «расцвет — зенит — хищничество — крах».</p><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>ок. −10 млрд лет</td><td>Сеть законов Вселенной Хэнъюань стабилизировалась; сформировались первые материальные плоскости; вселенная вошла в обитаемое состояние</td></tr><tr><td>ок. −8 млрд лет</td><td>На множестве материальных плоскостей зародилась первая разумная жизнь; начали пробиваться примитивные системы культивации</td></tr><tr><td>ок. −5 млрд лет</td><td>Хищнические системы культивации постепенно стали господствующими; сильные достигали быстрой эволюции, пожирая слабых</td></tr><tr><td>ок. −3 млрд лет</td><td>Вспыхнула первая вселенская хищническая война; цивилизации нескольких звёздных областей понесли сокрушительные удары</td></tr><tr><td>ок. −1 млрд лет</td><td>Стали проявляться изъяны хищнической системы; ускорился рост энтропии всей вселенной; ресурсы культивации постепенно истощались</td></tr><tr><td>ок. −500 млн лет</td><td>Появились первые мыслители, критикующие хищническую систему; начали зарождаться ростки симбиотической мысли</td></tr><tr><td>ок. −100 млн лет</td><td>В нескольких звёздных областях возникли небольшие экспериментальные симбиотические цивилизации, однако все были уничтожены хищническими цивилизациями</td></tr><tr><td>ок. −1 млн лет</td><td>Вселенная в целом вступила в «Великую Депрессию»; и число цивилизаций, и уровень культивации упали до исторического минимума</td></tr><tr><td>ок. −10 000 лет</td><td>Культиватор Первой Плоскости в ходе долгой культивации случайно ощутил стабильный узел в сети законов; механизм Якоря был открыт впервые</td></tr></tbody></table><h2 id="iv-эпоха-пробуждения-якоря-−10-000-до-−1000-лет" tabindex="-1">IV. Эпоха Пробуждения Якоря (−10 000 до −1000 лет) <a class="header-anchor" href="#iv-эпоха-пробуждения-якоря-−10-000-до-−1000-лет" aria-label="Permalink to &quot;IV. Эпоха Пробуждения Якоря (−10 000 до −1000 лет)&quot;">​</a></h2><p>Эпоха Пробуждения Якоря была переходным периодом механизма Якоря от открытия к первичному применению. Её ключевой чертой были постепенное созревание технологии Якоря и распространение симбиотической мысли.</p><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>−10 000 лет</td><td>Механизм Якоря был открыт впервые; первооткрыватель назвал его «Якорь» и начал систематическое исследование</td></tr><tr><td>−9000 лет</td><td>Первый искусственный Якорь был успешно установлен, доказав, что Якоря можно создавать и поддерживать искусственно</td></tr><tr><td>−8000 лет</td><td>Технология Якоря начала распространяться в узких кругах; появились первые культиваторы Якоря</td></tr><tr><td>−7000 лет</td><td>Было обнаружено, что Якорь может служить опорой межплоскостных соединений; удался первый зафиксированный переход между плоскостями при помощи Якоря</td></tr><tr><td>−6000 лет</td><td>Симбиотическая мысль начала сочетаться с технологией Якоря; появились первые теоретические труды о «Симбиозе Якоря»</td></tr><tr><td>−5000 лет</td><td>Был основан первый симбиотический город-государство на основе Якоря, доказавший осуществимость симбиотической системы</td></tr><tr><td>−4000 лет</td><td>Хищнические цивилизации атаковали симбиотические города-государства; те успешно оборонялись благодаря технологии Якоря</td></tr><tr><td>−3000 лет</td><td>Симбиотическая мысль распространилась в нескольких звёздных областях; всё больше цивилизаций начинали попытки симбиотической трансформации</td></tr><tr><td>−2000 лет</td><td>Состоялось первое «Великое Собрание Симбиоза Десяти Тысяч Рас»; представители десятков рас совместно обсуждали будущее симбиотической цивилизации</td></tr><tr><td>−1000 лет</td><td>Технология Якоря и симбиотическая мысль обрели условия для создания единой цивилизации; начался Период установления симбиотической системы</td></tr></tbody></table><h2 id="v-период-установления-симбиотическои-системы-−1000-до-−100-лет" tabindex="-1">V. Период установления симбиотической системы (−1000 до −100 лет) <a class="header-anchor" href="#v-период-установления-симбиотическои-системы-−1000-до-−100-лет" aria-label="Permalink to &quot;V. Период установления симбиотической системы (−1000 до −100 лет)&quot;">​</a></h2><p>Период установления симбиотической системы был ключевым периодом, в который институциональный каркас Симбиотической Цивилизации Якоря создавался с нуля.</p><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>−1000 лет</td><td>Был создан Комитет по разработке Симбиотической Конституции; началась разработка основного закона</td></tr><tr><td>−950 лет</td><td>Проект Симбиотической Конституции был завершён; начался широкий сбор мнений десяти тысяч рас</td></tr><tr><td>−900 лет</td><td>Симбиотическая Конституция была принята всенародным референдумом и вступила в силу; Симбиотическая Цивилизация Якоря была провозглашена</td></tr><tr><td>−850 лет</td><td>Три главные институции — Собрание Якоря, Симбиотический Исполнительный Комитет и Симбиотический Суд — были официально учреждены и начали действовать</td></tr><tr><td>−800 лет</td><td>Механизм подряда, связанного с результатом, начал внедряться по всей территории</td></tr><tr><td>−700 лет</td><td>Один за другим были приняты базовые законы, такие как Симбиотический Трудовой Закон и Закон о защите прав потребителей</td></tr><tr><td>−600 лет</td><td>Все пять сопутствующих законов — об образовании, медицине, жилье, окружающей среде и антимонопольный — были приняты и введены в действие</td></tr><tr><td>−500 лет</td><td>Официально начались работы по раскопке и систематизации Трёхсот Исходных Систем Культивации</td></tr><tr><td>−400 лет</td><td>Первые пятьдесят Исходных Систем Культивации завершили систематизацию и проверку</td></tr><tr><td>−300 лет</td><td>Был достигнут прорыв в технологическом применении Плода Умножения; технология стократного дедуктивного усиления достигла зрелости</td></tr><tr><td>−200 лет</td><td>Все Триста Систем завершили систематизацию и вступили в финальный этап проверки безопасности</td></tr><tr><td>−100 лет</td><td>Созрели условия для полного открытия Трёхсот Исходных Систем Культивации; начался период открытия</td></tr></tbody></table><h2 id="vi-период-открытия-трехсот-систем-−100-до-−50-лет" tabindex="-1">VI. Период открытия Трёхсот Систем (−100 до −50 лет) <a class="header-anchor" href="#vi-период-открытия-трехсот-систем-−100-до-−50-лет" aria-label="Permalink to &quot;VI. Период открытия Трёхсот Систем (−100 до −50 лет)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>−100 лет</td><td>Триста Исходных Систем Культивации были официально открыты бесплатно для всех живых существ вселенной</td></tr><tr><td>−90 лет</td><td>Число культиваторов за десять лет выросло в сто раз; «путь для каждого» был предварительно реализован</td></tr><tr><td>−80 лет</td><td>Три Исходные Основы (Дедуктивная Итерация, Жизненный Цикл и регулирование пространственных правовых принципов) стали самыми популярными системами</td></tr><tr><td>−70 лет</td><td>Появились первые культиваторы, достигшие высоких уровней по новым системам, что доказало эффективность систем</td></tr><tr><td>−60 лет</td><td>Сеть наставников была полностью создана; продвинутые культиваторы начали исполнять законную обязанность наставления начинающих культиваторов</td></tr><tr><td>−50 лет</td><td>Общий уровень культивации всего населения значительно вырос; созрели условия для Стратегии активации 20 %</td></tr></tbody></table><h2 id="vii-период-стратегии-активации-20-−50-лет-до-первого-года" tabindex="-1">VII. Период Стратегии активации 20 % (−50 лет до первого года) <a class="header-anchor" href="#vii-период-стратегии-активации-20-−50-лет-до-первого-года" aria-label="Permalink to &quot;VII. Период Стратегии активации 20 % (−50 лет до первого года)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>−50 лет</td><td>Стратегия активации 20 % была официально запущена: цель — за 50 лет активировать 20 % живых существ в Верховных Силачей Плоскости</td></tr><tr><td>−40 лет</td><td>Появились первые Верховные Силачи Плоскости; уровень активации достиг 5 %</td></tr><tr><td>−30 лет</td><td>Уровень активации достиг 10 %; Верховные Силачи Плоскости начали играть ключевую роль в обслуживании Якорей</td></tr><tr><td>−20 лет</td><td>Уровень активации достиг 15 %; общий уровень культивации вселенной совершил качественный скачок</td></tr><tr><td>−10 лет</td><td>Уровень активации достиг 18 %, приблизившись к стратегической цели</td></tr><tr><td>Первый год</td><td>Уровень активации достиг 20,3 %; Стратегия активации 20 % была полностью выполнена, и Симбиотическая Цивилизация Якоря вступила в новую эпоху</td></tr></tbody></table><h2 id="viii-эпоха-первого-возвышения-первыи-год-до-100" tabindex="-1">VIII. Эпоха первого возвышения (первый год до 100) <a class="header-anchor" href="#viii-эпоха-первого-возвышения-первыи-год-до-100" aria-label="Permalink to &quot;VIII. Эпоха первого возвышения (первый год до 100)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>Первый год</td><td>Симбиотическая цивилизация официально провозгласила вступление в эпоху возвышения; завершён первый этап Четырёхэтапного Пути Возвышения (Основание реальности)</td></tr><tr><td>20</td><td>Второй этап (Технологическое усиление) развернулся по всем направлениям; законы культивации и технологическая инженерия глубоко интегрировались</td></tr><tr><td>40</td><td>Технологии Зеркала Репликации и изолированного пространства достигли промышленного серийного производства; межплоскостная археология вступила в эпоху масштаба</td></tr><tr><td>60</td><td>Первые культиваторы возвышения сознания достигли высоких уровней; начался третий этап (Эволюция сознания)</td></tr><tr><td>80</td><td>Было завершено строительство инфраструктуры сферы сознания; технология переноса сознания предварительно созрела</td></tr><tr><td>100</td><td>Первое поэтапное возвышение увенчалось успехом; симбиотическая цивилизация в целом поднялась на пол-уровня измерения</td></tr></tbody></table><h2 id="ix-эпоха-республики-десяти-тысяч-рас-100-до-500" tabindex="-1">IX. Эпоха Республики Десяти Тысяч Рас (100 до 500) <a class="header-anchor" href="#ix-эпоха-республики-десяти-тысяч-рас-100-до-500" aria-label="Permalink to &quot;IX. Эпоха Республики Десяти Тысяч Рас (100 до 500)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>100</td><td>Республика Десяти Тысяч Рас была официально провозглашена; все разумные расы достигли равноправного союза в рамках симбиотической цивилизации</td></tr><tr><td>150</td><td>Завершено составление Реестра Десяти Тысяч Рас, охватившего все известные разумные расы</td></tr><tr><td>200</td><td>Межрасовые браки и культурное слияние стали нормой; начали появляться новые смешанные расы</td></tr><tr><td>300</td><td>Завершено распространение общего языка десяти тысяч рас; барьеры межрасового общения практически устранены</td></tr><tr><td>400</td><td>Наступил великий расцвет культур Десяти Тысяч Рас; традиционные культуры каждого народа получили защиту и развитие в симбиотическом каркасе</td></tr><tr><td>500</td><td>Республика Десяти Тысяч Рас вступила в период зрелости; условия межплоскостных исследований полностью созрели</td></tr></tbody></table><h2 id="x-эпоха-межплоскостных-исследовании-500-до-2000" tabindex="-1">X. Эпоха межплоскостных исследований (500 до 2000) <a class="header-anchor" href="#x-эпоха-межплоскостных-исследовании-500-до-2000" aria-label="Permalink to &quot;X. Эпоха межплоскостных исследований (500 до 2000)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>500</td><td>Официально запущена масштабная программа межплоскостных исследований; учреждено Управление Плоскостей</td></tr><tr><td>600</td><td>Исследовано более тысячи плоскостей; предварительно создана главная база координат плоскостей</td></tr><tr><td>800</td><td>Схема дистанционной археологии Зеркалом Репликации полностью созрела; межплоскостная археология вступила в золотой век</td></tr><tr><td>1000</td><td>Достигнут прорыв в технологии возврата времени; официально установлен принцип сначала наблюдение, потом ограниченное вмешательство</td></tr><tr><td>1200</td><td>Исследовано более ста тысяч плоскостей; установлены дипломатические отношения с десятками плоскостных цивилизаций</td></tr><tr><td>1500</td><td>Межплоскостные этические нормы полностью внедрены; взаимодействие цивилизаций вступило в эпоху регулирования</td></tr><tr><td>1800</td><td>Механизм предотвращения временных парадоксов полностью созрел; археология с возвратом времени достигла масштаба</td></tr><tr><td>2000</td><td>Межплоскостные исследования достигли блестящих результатов; условия эпохи межзвёздного симбиоза полностью созрели</td></tr></tbody></table><h2 id="xi-эпоха-межзвездного-симбиоза-2000-до-будущего" tabindex="-1">XI. Эпоха межзвёздного симбиоза (2000 до будущего) <a class="header-anchor" href="#xi-эпоха-межзвездного-симбиоза-2000-до-будущего" aria-label="Permalink to &quot;XI. Эпоха межзвёздного симбиоза (2000 до будущего)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Временная веха</th><th>Крупное событие</th></tr></thead><tbody><tr><td>2000</td><td>Эпоха межзвёздного симбиоза официально началась; четвёртый этап (Межзвёздный симбиоз) развернулся по всем направлениям</td></tr><tr><td>2500 (перспектива)</td><td>Предварительно создана вселенская сеть Якорей, охватывающая все исследованные плоскости</td></tr><tr><td>3000 (перспектива)</td><td>Межплоскостная симбиотическая система созрела; десять тысяч рас достигли истинного симбиоза в масштабах вселенной</td></tr><tr><td>5000 (перспектива)</td><td>Завершено общее возвышение вселенной; Вселенная Хэнъюань вступила в состояние существования в более высоком измерении</td></tr><tr><td>Будущее (перспектива)</td><td>Симбиотическая Цивилизация Якоря продолжает исследовать просторы за пределами вселенной, распространяя идею симбиоза на более широкие формы существования</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Краткая таблица летописи — это эпос борьбы Симбиотической Цивилизации Якоря: от невежества к пробуждению, от слабости к силе, от собственной плоскости ко всей вселенной. Смена каждой эпохи — свидетельство победы симбиотической идеи над хищнической и цивилизационного прогресса над варварским упадком. История — не пыль прошлого, а семя будущего: понять эту историю значит понять, откуда пришла симбиотическая цивилизация и куда она идёт.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>70-纪元划分总表 (Сводная таблица деления эпох)</li><li>72-锚点觉醒纪元 (Эпоха Пробуждения Якоря)</li><li>79-星际共生时代展望 (Перспективы Эпохи Межзвёздного Симбиоза)</li></ul>',32)])])}const x=d(h,[["render",i]]);export{u as __pageData,x as default};
